let consolidatedText = "";

for (const item of $input.all()) {
  consolidatedText += `-----\nsender: "${item.json.From}"\nbody: "${item.json.snippet}"\n`;
}

// Return as a single item containing the combined text
return [{ json: { result: consolidatedText.trim() } }];

// 1. Get incoming item
const item = $input.first().json;

let rawText = "";
let emailSubject = "Consolidated Mail Update";

// Handle case where the text field contains a stringified JSON object
try {
  if (typeof item.text === 'string' && item.text.trim().startsWith('{')) {
    const parsed = JSON.parse(item.text);
    rawText = parsed.text || "";
    emailSubject = parsed.subject || emailSubject;
  } else {
    rawText = item.text || "";
    emailSubject = item.subject || emailSubject;
  }
} catch (e) {
  rawText = item.text || "";
  emailSubject = item.subject || emailSubject;
}

// 2. Clean up literal escaped newlines if present
rawText = rawText.replace(/\\n/g, '\n');

// 3. Split entries by bullets or line breaks to separate each sender
// This matches patterns like "• INDmoney:" or similar bulleted sections
const entries = rawText
  .split(/(?=•|\n\s*•)/)
  .map(entry => entry.trim())
  .filter(entry => entry.length > 0);

// 4. Format each sender's message into its own distinct card/box
const formattedEntries = entries.map(entry => {
  // Remove the bullet character itself since we are using structured cards
  let cleaned = entry.replace(/^[•\-\*]\s*/, '');

  // Convert Markdown bold (**text**) to HTML bold tags (<b>text</b>)
  cleaned = cleaned.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

  return `
    <div style="background-color: #f8f9fa; border-left: 4px solid #0066cc; padding: 14px 16px; margin-bottom: 12px; border-radius: 4px;">
      <div style="font-size: 14px; color: #333333; line-height: 1.6;">
        ${cleaned}
      </div>
    </div>
  `;
}).join('');

// 5. Build full HTML document body without repeating the header title inside content
const htmlBody = `
<!DOCTYPE html>
<html>
<body style="font-family: Arial, sans-serif; background-color: #f4f6f8; padding: 20px; margin: 0;">
  <div style="max-width: 600px; background: #ffffff; padding: 24px; border-radius: 8px; border: 1px solid #e0e0e0; margin: 0 auto;">
    <h2 style="color: #1a1a1a; margin-top: 0; padding-bottom: 12px; border-bottom: 2px solid #eaeaea; font-size: 20px;">
      ${emailSubject}
    </h2>
    <div style="margin-top: 20px;">
      ${formattedEntries}
    </div>
  </div>
</body>
</html>
`;

// 6. Return output for n8n email node
return [{
  json: {
    subject: emailSubject,
    html: htmlBody
  }
}];
